<?php
defined('ABSPATH') || exit;
final class Bazarche_Yar_Admin {
 const OPTION='bazarche_yar_settings';
 public function __construct(){add_action('admin_menu',array($this,'menu'));add_action('admin_init',array($this,'settings'));add_action('admin_post_bazarche_yar_sync',array($this,'sync_action'));}
 public static function get_settings(){return wp_parse_args(get_option(self::OPTION,array()),array('base_url'=>'https://bazarcha.ir','api_key'=>'','user_id'=>'','storage_uuid'=>'','default_category_id'=>'','brand'=>'','auto_sync'=>0));}
 public function menu(){add_menu_page('بازارچه‌یار','بازارچه‌یار','manage_woocommerce','bazarche-yar',array($this,'products'),'dashicons-update',56);add_submenu_page('bazarche-yar','تنظیمات','تنظیمات','manage_woocommerce','bazarche-yar-settings',array($this,'settings_page'));}
 public function settings(){register_setting('bazarche_yar_group',self::OPTION,array($this,'sanitize'));}
 public function sanitize($in){$old=self::get_settings();$in=is_array($in)?$in:array();return array('base_url'=>esc_url_raw(untrailingslashit(trim($in['base_url']??''))),'api_key'=>!empty($in['api_key'])?sanitize_text_field($in['api_key']):$old['api_key'],'user_id'=>absint($in['user_id']??0),'storage_uuid'=>sanitize_text_field($in['storage_uuid']??''),'default_category_id'=>absint($in['default_category_id']??0),'brand'=>sanitize_text_field($in['brand']??''),'auto_sync'=>empty($in['auto_sync'])?0:1);}
 public function settings_page(){if(!current_user_can('manage_woocommerce'))return;$s=self::get_settings();echo '<div class="wrap"><h1>تنظیمات بازارچه‌یار</h1><form method="post" action="options.php">';settings_fields('bazarche_yar_group');echo '<table class="form-table"><tbody>';
 $this->field('base_url','آدرس پایه API',$s['base_url'],'url');$this->field('api_key','کلید API (برای حفظ کلید قبلی خالی بگذارید)','');$this->field('user_id','شناسه کاربر',$s['user_id'],'number');$this->field('storage_uuid','UUID انبار',$s['storage_uuid']);$this->field('default_category_id','شناسه دسته‌بندی پیش‌فرض بازارچه',$s['default_category_id'],'number');$this->field('brand','برند پیش‌فرض (اختیاری)',$s['brand']);
 echo '<tr><th>همگام‌سازی خودکار</th><td><label><input type="checkbox" name="'.esc_attr(self::OPTION).'[auto_sync]" value="1" '.checked(1,$s['auto_sync'],false).'> پس از تغییر محصول یا موجودی در ووکامرس به صف ارسال شود</label></td></tr></tbody></table>';submit_button('ذخیره تنظیمات');echo '</form><p>هدر احراز هویت طبق مستندات: <code>X-API-KEY</code>. آدرس‌ها و پارامترها از مستندات API بازارچه تنظیم شده‌اند.</p></div>';}
 private function field($key,$label,$value,$type='text'){echo '<tr><th><label>'.esc_html($label).'</label></th><td><input class="regular-text" type="'.esc_attr($type).'" name="'.esc_attr(self::OPTION).'['.esc_attr($key).']" value="'.esc_attr($value).'"></td></tr>';}
 public function products(){if(!current_user_can('manage_woocommerce'))return;echo '<div class="wrap"><h1>بازارچه‌یار</h1>';if(!class_exists('WooCommerce')){echo '<div class="notice notice-error"><p>ووکامرس باید فعال باشد.</p></div></div>';return;}if(isset($_GET['by_result']))echo '<div class="notice notice-info"><p>'.esc_html(sanitize_text_field(wp_unslash($_GET['by_result']))).'</p></div>';
 $items=wc_get_products(array('limit'=>50,'status'=>array('publish','private'),'type'=>array('simple','variable'),'orderby'=>'date','order'=>'DESC'));echo '<p>همگام‌سازی یک‌طرفه از ووکامرس به بازارچه؛ نمایش ۵۰ محصول اخیر.</p><table class="widefat striped"><thead><tr><th>محصول</th><th>نوع</th><th>UUID محصول</th><th>آخرین همگام‌سازی</th><th>خطا</th><th>عملیات</th></tr></thead><tbody>';
 foreach($items as $p){$id=$p->get_id();$uuid=get_post_meta($id,Bazarche_Yar_Sync::PRODUCT_UUID,true);$last=get_post_meta($id,Bazarche_Yar_Sync::LAST_SYNC,true);$err=get_post_meta($id,Bazarche_Yar_Sync::LAST_ERROR,true);echo '<tr><td>'.wp_kses_post($p->get_image(array(40,40))).' '.esc_html($p->get_name()).' (#'.absint($id).')</td><td>'.esc_html($p->get_type()).'</td><td>'.esc_html($uuid?:'—').'</td><td>'.esc_html($last?:'—').'</td><td>'.esc_html($err?:'—').'</td><td><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="bazarche_yar_sync"><input type="hidden" name="product_id" value="'.absint($id).'">'.wp_nonce_field('bazarche_yar_sync_'.$id,'_wpnonce',true,false).'<button class="button button-primary">همگام‌سازی</button></form></td></tr>';}
 echo '</tbody></table></div>';}
 public function sync_action(){$id=absint($_POST['product_id']??0);if(!$id||!current_user_can('edit_post',$id))wp_die('دسترسی غیرمجاز');check_admin_referer('bazarche_yar_sync_'.$id);if(!class_exists('WooCommerce'))wp_die('ووکامرس فعال نیست');$r=(new Bazarche_Yar_Sync(self::get_settings()))->sync_product($id);$msg=is_wp_error($r)?$r->get_error_message():'همگام‌سازی با موفقیت انجام شد.';wp_safe_redirect(add_query_arg(array('page'=>'bazarche-yar','by_result'=>$msg),admin_url('admin.php')));exit;}
}